// Trackball control index — record JAH-GPC-TRACKBALL-000001
// Property of Justin Addam Higgins (JAH). Deterministic: same inputs, same output.
var m = {"dpi": 1600, "buttons": 5};
var value = (m.dpi/1000*m.buttons);
if (!isFinite(value)) { console.log('DEMO_FAIL|JAH-GPC-TRACKBALL-000001|non-finite'); process.exit(1); }
console.log('DEMO_OK|JAH-GPC-TRACKBALL-000001|' + value.toFixed(2) + ' control index');

